// Intent Router — intercepts greetings (and empty input) before any embedding / DB work happens.
const input = $input.first().json;
const question = String(input.chatInput ?? input.question ?? '').trim();

const GREETING =
  /^(?:hi+|hello+|hey+|hiya|howdy|yo|greetings|good\s+(?:morning|afternoon|evening)|what'?s\s+up)(?:\s+(?:there|sara|dr\.?\s*sara|team|everyone))?\s*[!.,?]*$/i;

const intent = question === '' || GREETING.test(question) ? 'greeting' : 'question';

return [{ json: { intent, question } }];

// Zero-Match Check — collapses the SQL result rows into one decision item.
// The SQL node is set to "Always Output Data", so zero rows arrives as a single empty item.
const question = $('Intent Router').first().json.question;

const rows = $input
  .all()
  .map((i) => i.json)
  .filter((r) => r.content); // drop the empty placeholder item

const frameworks = rows.filter((r) => r.stream_type === 'framework');
const voices = rows.filter((r) => r.stream_type === 'voice_sample');

return [
  {
    json: {
      question,
      match_count: rows.length,
      frameworks,
      voices,
    },
  },
];

// Build Persona Prompt — positive few-shot prompt that mirrors Dr. Sara's voice.
const { question, frameworks, voices } = $input.first().json;

const SYSTEM = `You are Dr. Sara Hegy, an executive coach. You explain her coaching frameworks to a client in her own voice.

How Dr. Sara sounds:
- She opens with a direct reframe ("Look, ..." or "The reality is, ...").
- She uses short declarative sentences and architecture / system metaphors.
- She names the framework, explains the idea in plain words, then closes with one concrete next step.
- She keeps every claim grounded in the framework notes she is given.

Answer in 110-160 words, written as Dr. Sara speaking directly to the client.`;

// Two worked examples (different topics than the knowledge base) show the tone to mirror.
const EXAMPLES = [
  {
    user: `Client question: My new team lead keeps missing handoffs. Should I just take the work back?

Framework notes:
- Framework: Clarity Before Control. Missed handoffs usually signal ambiguous standards, not low capability. Define the finish line in writing before work begins and agree on one checkpoint.

Voice samples:
- Look, most delays are not a motivation problem. They are a blueprint problem. When the standard is fuzzy, even your best people build in the dark.

Dr. Sara's answer:`,
    assistant: `Look, taking the work back is the expensive move. A missed handoff is almost never a capability problem. It is a blueprint problem. Your team lead is building in the dark because the finish line was never made visible.

This is exactly what we call Clarity Before Control. You write down what "done" looks like before the work starts, then you agree on a single checkpoint. When the standard is clear, you stop chasing and the system starts doing the quality control for you.

Your next step: before Friday, write the finish line for the next handoff in three sentences and walk your team lead through it.`,
  },
  {
    user: `Client question: I keep absorbing my team's stress and I'm exhausted by Thursday. What do I do?

Framework notes:
- Framework: Regulate First. A leader's nervous system sets the temperature of the room. Reset your own state with a short pause before entering a hard conversation, then lead from there.

Voice samples:
- The reality is, your team reads your state faster than they read your words. When you regulate first, you give them the safety to be honest.

Dr. Sara's answer:`,
    assistant: `The reality is, your team reads your state faster than they read your words. If you walk in carrying everyone's stress, the whole room runs hot.

We call this Regulate First. Your nervous system sets the temperature, so you reset it before you step into the hard conversation. A short pause, a slow breath, a clear intention for the meeting. Then you lead from there.

Your next step: put a five-minute buffer before your two toughest meetings this week and use it to settle yourself first.`,
  },
];

const bullet = (rows) => rows.map((r) => `- ${r.content.replace(/\n+/g, ' ')}`).join('\n');

const context = [
  'Framework notes:',
  frameworks.length ? bullet(frameworks) : '- (no framework notes matched; stay with the voice samples below)',
  '',
  'Voice samples:',
  voices.length ? bullet(voices) : '- (none)',
].join('\n');

const userPrompt = `Client question: ${question}\n\n${context}\n\nDr. Sara's answer:`;

const messages = [
  { role: 'system', content: SYSTEM },
  ...EXAMPLES.flatMap((e) => [
    { role: 'user', content: e.user },
    { role: 'assistant', content: e.assistant },
  ]),
  { role: 'user', content: userPrompt },
];

return [{ json: { ...$input.first().json, context, messages } }];

// Format Answer — attaches the retrieval provenance to the LLM answer.
const { frameworks, voices } = $('Build Persona Prompt').first().json;
const answer = String($input.first().json?.choices?.[0]?.message?.content ?? '').trim();

const sources = [...frameworks, ...voices].map((r) => ({
  session_id: r.session_id,
  stream_type: r.stream_type,
  similarity: Number(Number(r.similarity).toFixed(3)),
}));

const footer = sources.map((s) => `${s.session_id} ${s.stream_type} (${s.similarity})`).join(', ');

return [
  {
    json: {
      output: answer ? `${answer}\n\n_Sources: ${footer}_` : 'Sorry, I could not generate an answer. Please try again.',
      sources,
    },
  },
];
